    eu = acc.EU + row.amount_cents if row.region == "EU" else acc.EU
    apac = acc.APAC + row.amount_cents if row.region == "APAC" else acc.APAC
    return { NA: na, EU: eu, APAC: apac }
}
submitted = submit_result({ answer: { NA: totals.NA, EU: totals.EU, APAC: totals.APAC } })
return { totals: totals, submitted: submitted }
